#pragma once

#include <stdexcept>
#include <mutex>

namespace inventory_ledger {

class stock_ledger {
public:
    stock_ledger() = default;

    void begin() {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (m_active) {
            throw std::runtime_error("Ledger is already active");
        }
        m_active = true;
        m_quantity = 0;
    }

    void receive(int amount) {
        validate_and_update(amount, true);
    }

    void dispatch(int amount) {
        validate_and_update(amount, false);
    }

    void end() {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (!m_active) {
            throw std::runtime_error("Ledger is not active");
        }
        m_active = false;
        m_quantity = 0;
    }

    int quantity() {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (!m_active) {
            throw std::runtime_error("Ledger is not active");
        }
        return m_quantity;
    }

private:
    void validate_and_update(int amount, bool is_receive) {
        if (amount <= 0) {
            throw std::runtime_error("Amount must be positive");
        }

        std::lock_guard<std::mutex> lock(m_mutex);
        if (!m_active) {
            throw std::runtime_error("Ledger is not active");
        }

        int current = m_quantity;
        if (is_receive) {
            m_quantity = current + amount;
        } else {
            if (amount > current) {
                throw std::runtime_error("Insufficient quantity for dispatch");
            }
            m_quantity = current - amount;
        }
    }

    std::mutex m_mutex;
    bool m_active = false;
    int m_quantity = 0;
};

}  // namespace inventory_ledger
